func TestDryRunResponseShape(t *testing.T) {
	tests := []struct {
		name        string
		accept      string
		contentType string
		body        string
	}{
		{
			name:        "prefer JSON from weighted streaming accept",
			accept:      "application/json;q=1, text/event-stream;q=0",
			contentType: "application/json",
			body:        "{}",
		},
		{
			name:        "preserve vendor JSON type",
			accept:      "application/vnd.api+json",
			contentType: "application/vnd.api+json",
			body:        "{}",
		},
		{
			name:        "preserve non-quality parameters",
			accept:      "text/csv; charset=utf-8",
			contentType: "text/csv; charset=utf-8",
		},
		{
			name:        "preserve binary type",
			accept:      "application/octet-stream",
			contentType: "application/octet-stream",
		},
		{
			name:        "wildcard falls back to JSON",
			accept:      "*/*",
			contentType: "application/json",
			body:        "{}",
		},
		{
			name:        "empty accept falls back to JSON",
			contentType: "application/json",
			body:        "{}",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req, err := http.NewRequest(http.MethodGet, "https://example.com", nil)
			require.NoError(t, err)
			req.Header.Set("Accept", tt.accept)

			resp, err := (&client.DryRunClient{Stderr: io.Discard}).Do(req)
			require.NoError(t, err)
			t.Cleanup(func() { _ = resp.Body.Close() })

			body, err := io.ReadAll(resp.Body)
			require.NoError(t, err)
			require.Equal(t, tt.contentType, resp.Header.Get("Content-Type"))
			require.Equal(t, tt.body, string(body))
		})
	}
}

