	responseBody := `{"clientSecret":"response-secret","data":"` + encoded + `"}`
	req, err := http.NewRequest(http.MethodPost, "https://debug-user:debug-pass@example.com/v1/items?signature=secret", strings.NewReader(requestBody))
	require.NoError(t, err)
