	require.NotContains(t, stderr.String(), encoded)
	require.NotContains(t, stderr.String(), "signature=secret")
	require.NotContains(t, stderr.String(), "debug-pass")
	require.GreaterOrEqual(t, strings.Count(stderr.String(), "<bytes:96>"), 2)
