func TestDryRunIntentJQPresetAndCallerJQ(t *testing.T) {
	base := []string{"invite", "test", "--dry-run"}

	human := NewCLITestHarness(t)
	require.NoError(t, human.RunRaw(base))
	require.Empty(t, human.GetStdout(), "an intent-declared jq preset must not create synthetic output")
	require.Contains(t, human.GetStderr(), "[DRY-RUN]")

	machine := NewCLITestHarness(t)
	args := append(append([]string{}, base...), "--jq", ".field_that_does_not_exist")
	require.NoError(t, machine.RunRaw(args))
	require.Empty(t, machine.GetStderr())
	require.Contains(t, machine.GetStdout(), `"dry_run":true`, "caller jq selects previews but must not filter them")
}
